using System;using System.Collections.Generic;using System.Net.Http;using System.Threading;using System.Threading.Tasks;
public static class TokenRenewal {
 static readonly SemaphoreSlim twitch=new SemaphoreSlim(1),youtube=new SemaphoreSlim(1);
 internal static Func<HttpClient> Client=()=>new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(15)};
 static async Task<object> Exchange(string url,Dictionary<string,string> body){using(var http=Client())using(var response=await http.PostAsync(url,new FormUrlEncodedContent(body))){if(!response.IsSuccessStatusCode)throw new TwitchSignInRequired(response.StatusCode==System.Net.HttpStatusCode.BadRequest||response.StatusCode==System.Net.HttpStatusCode.Unauthorized?"Sign-in permission expired or was revoked. Reconnect this account.":"Could not renew sign-in right now. Try again shortly.");return Protocol.Json.DeserializeObject(await response.Content.ReadAsStringAsync());}}
 public static async Task<TwitchTokens> Twitch(bool force=false,string previous=null){await twitch.WaitAsync();try{var t=TwitchVault.Read();if(t==null)throw new TwitchSignInRequired("Connect Twitch first.");if(t.Expires>DateTime.UtcNow.AddMinutes(2)&&(!force||t.Access!=previous))return t;var r=await Exchange("https://id.twitch.tv/oauth2/token",new Dictionary<string,string>{{"client_id",DirectTwitch.ClientId},{"grant_type","refresh_token"},{"refresh_token",t.Refresh}});var access=Protocol.Pick(r,"access_token");if(access=="")throw new TwitchSignInRequired("Twitch could not renew access. Reconnect.");double seconds;if(!double.TryParse(Protocol.Pick(r,"expires_in"),out seconds))seconds=3600;var latest=TwitchVault.Read();if(latest==null||latest.Refresh!=t.Refresh)throw new TwitchSignInRequired("Twitch account changed. Try again.");var refresh=Protocol.Pick(r,"refresh_token");t=new TwitchTokens{Access=access,Refresh=refresh==""?t.Refresh:refresh,Expires=DateTime.UtcNow.AddSeconds(seconds)};TwitchVault.Save(t);return t;}finally{twitch.Release();}}
 public static async Task<YouTubeTokens> YouTube(bool force=false,string previous=null){await youtube.WaitAsync();try{var t=AccountStore.Read<YouTubeTokens>("youtube");var c=AccountStore.Read<GoogleClient>("google-client");if(t==null||c==null||t.ClientId!=c.ClientId)throw new TwitchSignInRequired("Connect YouTube first.");if(t.Expires>DateTime.UtcNow.AddMinutes(2)&&(!force||t.Access!=previous))return t;var r=await Exchange("https://oauth2.googleapis.com/token",new Dictionary<string,string>{{"client_id",c.ClientId},{"client_secret",c.ClientSecret},{"grant_type","refresh_token"},{"refresh_token",t.Refresh}});var access=Protocol.Pick(r,"access_token");if(access=="")throw new TwitchSignInRequired("YouTube could not renew access. Reconnect.");double seconds;if(!double.TryParse(Protocol.Pick(r,"expires_in"),out seconds))seconds=3600;var latest=AccountStore.Read<YouTubeTokens>("youtube");if(latest==null||latest.Refresh!=t.Refresh)throw new TwitchSignInRequired("YouTube account changed. Try again.");var refresh=Protocol.Pick(r,"refresh_token");t=new YouTubeTokens{ClientId=c.ClientId,Access=access,Refresh=refresh==""?t.Refresh:refresh,Expires=DateTime.UtcNow.AddSeconds(seconds)};AccountStore.Save("youtube",t);return t;}finally{youtube.Release();}}
}
